import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 11 One good turn deserves another","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 11 One good turn deserves another","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 10 Not for jazz","link":"/life/english/new-concept/book-2/unit-01/lesson-010"},"next":{"text":"第二册：实践与进步 · Lesson 12 Goodbye and good luck","link":"/life/english/new-concept/book-2/unit-01/lesson-012"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 10 Not for jazz","link":"/life/english/new-concept/book-2/unit-01/lesson-010"},"next":{"text":"第二册：实践与进步 · Lesson 12 Goodbye and good luck","link":"/life/english/new-concept/book-2/unit-01/lesson-012"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-011.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-011.md"}'),r={name:"life/english/new-concept/book-2/unit-01/lesson-011.md"};function l(i,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-11-one-good-turn-deserves-another" tabindex="-1">第二册：实践与进步 · Lesson 11 One good turn deserves another <a class="header-anchor" href="#第二册-实践与进步-·-lesson-11-one-good-turn-deserves-another" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 11 One good turn deserves another&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>朋友借出一本书，后来又得到对方的帮助；练习区分借入与借出并连接已完成的行为。本课的语言观察是：has lent 说明已经发生且仍与当前相关的借出行为；borrow 的主语是借入者，lend 的主语是借出者，二者不能按中文“借”互换。完成学习后，请写一次互助经历，明确谁借入、谁借出，以及归还安排。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>borrow</td><td>/ˈbɒrəʊ/</td><td>v.</td><td>借入</td><td>borrow a book</td></tr><tr><td>lend</td><td>/lend/</td><td>v.</td><td>借出</td><td>lend a hand</td></tr><tr><td>repay</td><td>/rɪˈpeɪ/</td><td>v.</td><td>偿还</td><td>repay a loan</td></tr><tr><td>favour</td><td>/ˈfeɪvə/</td><td>n.</td><td>帮忙</td><td>do a favour</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>borrow something from somebody — 向某人借入某物</li><li>do somebody a favour — 帮某人一个忙</li></ul><h2 id="语法讲解-现在完成时与过去时间" tabindex="-1">语法讲解：现在完成时与过去时间 <a class="header-anchor" href="#语法讲解-现在完成时与过去时间" aria-label="Permalink to &quot;语法讲解：现在完成时与过去时间&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has lent 说明已经发生且仍与当前相关的借出行为；borrow 的主语是借入者，lend 的主语是借出者，二者不能按中文“借”互换。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Ravi has lent me his bicycle for the weekend.</p></blockquote><p>拉维把自行车借给了我，供周末使用。</p><p>Ravi 是借出者，has lent 是完成时，me 是接收者，for the weekend 说明借用时段。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>borrow me a bicycle 通常不表示借给我；应说 lend me a bicycle。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>比较 lent 和 lend 的词尾，录下 has lent me，避免吞掉整个助动词。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Ravi has lent me his bicycle for the weekend. I helped him repair a shelf last week. We try to return things on time.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一次互助经历，明确谁借入、谁借出，以及归还安排。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Ravi 是借出者，has lent 是完成时，me 是接收者，for the weekend 说明借用时段。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：borrow me a bicycle 通常不表示借给我；应说 lend me a bicycle。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 lend 的过去分词：Ravi has ___ me his bicycle.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lent</p><p><strong>解析：</strong> lend 的过去式和过去分词都是 lent。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>我上周帮助拉维做了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I helped him repair a shelf.</p><p><strong>解析：</strong> 示范说的是修架子，不是修自行车。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 borrow 改写 Ravi lent me a bicycle，保持事实不变。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I borrowed a bicycle from Ravi.</p><p><strong>解析：</strong> 借入者 I 作主语，来源用 from Ravi。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在完成时与过去时间。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-010">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-012">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
